package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="webhook_delivery_logs") public class WebhookDeliveryLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="event_id") private String eventId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subscription_id") private WebhookSubscription subscription; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shipment_id") private Shipment shipment; @Column(name="event_type") private String eventType; @Column(name="attempt_number") private int attemptNumber; @Enumerated(EnumType.STRING) private Statuses.WebhookDeliveryStatus status; @Column(name="http_status") private Integer httpStatus; @Column(name="error_message") private String errorMessage; @Column(name="created_at") private Instant createdAt; @PrePersist void created(){createdAt=Instant.now();} public void setEventId(String v){eventId=v;} public void setSubscription(WebhookSubscription v){subscription=v;} public void setShipment(Shipment v){shipment=v;} public void setEventType(String v){eventType=v;} public void setAttemptNumber(int v){attemptNumber=v;} public void setStatus(Statuses.WebhookDeliveryStatus v){status=v;} public void setHttpStatus(Integer v){httpStatus=v;} public void setErrorMessage(String v){errorMessage=v;} }
